#!/usr/bin/env python3
import re
import sys
from pathlib import Path

ENTRY = re.compile(
    r'^TAKA_DIAG\(\s*([A-Za-z_][A-Za-z0-9_]*)\s*,\s*"([^"]+)"\s*,\s*DIAG_[A-Z_]+'
    r'\s*,\s*DIAG_DOMAIN_[A-Z_]+\s*,\s*"((?:[^"\\]|\\.)*)"\s*\)\s*$'
)


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: gen_diagnostics.py <diagnostics.def> <output.h>", file=sys.stderr)
        return 2
    source = Path(sys.argv[1])
    target = Path(sys.argv[2])
    names = set()
    ids = set()
    lines = [
        "#pragma once",
        "/* Generated by tools/gen_diagnostics.py from diagnostics.def. */",
    ]
    for number, raw in enumerate(source.read_text().splitlines(), 1):
        line = raw.strip()
        if not line or not line.startswith("TAKA_DIAG("):
            continue
        match = ENTRY.match(line)
        if not match:
            print(f"{source}:{number}: malformed TAKA_DIAG entry", file=sys.stderr)
            return 1
        name, ident, message = match.groups()
        if name in names:
            print(f"{source}:{number}: duplicate diagnostic name {name}", file=sys.stderr)
            return 1
        if ident in ids:
            print(f"{source}:{number}: duplicate diagnostic id {ident}", file=sys.stderr)
            return 1
        names.add(name)
        ids.add(ident)
        lines.append(f'#define TAKA_MSG_{name} "{message}"')
    lines.append("")
    target.write_text("\n".join(lines))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
